effect.shader:
vec3 u_xlat0;
vec4 u_xlat1;
mediump vec3 u_xlat16_1;
mediump vec3 u_xlat16_2;
mediump vec3 u_xlat16_5;
float u_xlat9;
mediump float u_xlat16_10;
void main()
{
    u_xlat0.xyz = (-vs_TEXCOORD3.xyz) + _WorldSpaceCameraPos.xyz;
    u_xlat9 = dot(u_xlat0.xyz, u_xlat0.xyz);
    u_xlat9 = inversesqrt(u_xlat9);
    u_xlat16_1.xyz = u_xlat0.xyz * vec3(u_xlat9) + _WorldSpaceLightPos0.xyz;
    u_xlat16_10 = dot(u_xlat16_1.xyz, u_xlat16_1.xyz);
    u_xlat16_10 = inversesqrt(u_xlat16_10);
    u_xlat16_1.xyz = vec3(u_xlat16_10) * u_xlat16_1.xyz;
    u_xlat16_1.x = dot(vs_TEXCOORD2.xyz, u_xlat16_1.xyz);
    u_xlat16_1.x = max(u_xlat16_1.x, 0.0);
    u_xlat0.x = log2(u_xlat16_1.x);
    u_xlat16_1.x = _Shininess * 128.0;
    u_xlat0.x = u_xlat0.x * u_xlat16_1.x;
    u_xlat0.x = exp2(u_xlat0.x);
    u_xlat1 = texture(inputImg, acScreenNorm.xy);
    u_xlat0.x = u_xlat0.x * u_xlat1.w;
    u_xlat16_2.xyz = _LightColor0.xyz * _SpecColor.xyz;
    u_xlat0.xyz = u_xlat0.xxx * u_xlat16_2.xyz;
    u_xlat16_2.x = dot(vs_TEXCOORD2.xyz, _WorldSpaceLightPos0.xyz);
    u_xlat16_2.x = max(u_xlat16_2.x, 0.0);
    u_xlat16_5.xyz = u_xlat1.xyz * _LightColor0.xyz;
    u_xlat0.xyz = u_xlat16_5.xyz * u_xlat16_2.xxx + u_xlat0.xyz;
    u_xlat16_2.xyz = u_xlat1.xyz * vs_TEXCOORD4.xyz + u_xlat0.xyz;
    u_xlat0.x = u_xlat1.w * _opacity;
    fragColor.w = u_xlat0.x;
    u_xlat0.xyz = texture(Cube, vs_TEXCOORD1.xyz).xyz;
    fragColor.xyz = u_xlat0.xyz * _reflection_color.xyz + u_xlat16_2.xyz;
    return;
}
